    // Every frontend reports exactly VIB006, with the ban message. (Before roslyn-linear-switch, Stage-0 and the Analyzer
    // also reported a knock-on VIB001 for the switch's own scrutinee, and only VIB001 on a guarded NoneType arm.)
    [Theory]
    [MemberData(nameof(BannedArms))]
    public void BannedArmsAreLinearViolations(string name, string source)
    {
        WithSource(name, source, path =>
        {
            var compilation = VibraniumCompilerDriver.CreateCompilationFromPath(path, "SelfLinearUnionSwitchBanned", includeStd: true);
            Assert.DoesNotContain(compilation.GetDiagnostics(), diagnostic => diagnostic.Severity == DiagnosticSeverity.Error);
            var stage0 = VibraniumFrontend.CompileAndCheck(compilation).Diagnostics;
            Assert.Equal(new[] { "VIB006" }, stage0.Select(diagnostic => diagnostic.Id).Distinct().ToArray());
            Assert.Contains(stage0, diagnostic => diagnostic.Message == BanMessage);
            var analyzer = compilation.WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new VibraniumDiagnosticAnalyzer()))
                .GetAnalyzerDiagnosticsAsync().GetAwaiter().GetResult();
            Assert.Equal(new[] { "VIB006" }, analyzer.Select(diagnostic => diagnostic.Id).Distinct().ToArray());
            Assert.Contains(analyzer, diagnostic => diagnostic.GetMessage() == BanMessage);
            var self = RunSelf(path);
            Assert.Equal(1, self.Exit);
            Assert.Equal(new[] { "VIB006" }, SelfIds(self));
            Assert.Contains("error VIB006: " + BanMessage, self.Output + self.Error, StringComparison.Ordinal);
        });
    }

