    // One ban diagnostic per offending arm, at the first token of the arm's pattern: a guarded arm, then a repeated variant.
    // Stage-0 and the Analyzer report the ban at the same positions as vib-self.
    [Theory]
    [MemberData(nameof(Anchors))]
    public void BanIsReportedOncePerOffendingArmAtItsPattern(string name, string source, string expectedLocations)
    {
        WithSource(name, source, path =>
        {
            var self = RunSelf(path);
            Assert.Equal(1, self.Exit);
            string[] locations = Regex.Matches(self.Output + self.Error, @"Program\.cs\((\d+,\d+)\): error VIB006: " + Regex.Escape(BanMessage))
                .Select(match => match.Groups[1].Value).ToArray();
            Assert.Equal(expectedLocations.Split(';'), locations);
            var compilation = VibraniumCompilerDriver.CreateCompilationFromPath(path, "SelfLinearUnionSwitchAnchors", includeStd: true);
            var stage0 = VibraniumFrontend.CompileAndCheck(compilation).Diagnostics
                .Where(diagnostic => diagnostic.Message == BanMessage)
                .Select(diagnostic => $"{diagnostic.Span.Line},{diagnostic.Span.Column}").ToArray();
            Assert.Equal(expectedLocations.Split(';'), stage0);
            var analyzer = compilation.WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new VibraniumDiagnosticAnalyzer()))
                .GetAnalyzerDiagnosticsAsync().GetAwaiter().GetResult()
                .Where(diagnostic => diagnostic.GetMessage() == BanMessage)
                .Select(diagnostic => diagnostic.Location.GetLineSpan().StartLinePosition)
                .OrderBy(position => position)
                .Select(position => $"{position.Line + 1},{position.Character + 1}").ToArray();
            Assert.Equal(expectedLocations.Split(';'), analyzer);
        });
    }

