        yield return new object[] { "n19-x05-none-or-not-none", "WriteLine(F(Some(4)));WriteLine(F(None));static int F(Option<int> o){switch(o){case NoneType or not NoneType:return 1;}}\n", "1\n1\n" };
        yield return new object[] { "n19-x06-result-ok-or-not-ok", "WriteLine(F(Ok(4)));WriteLine(F(Err(5)));static int F(Result<int, int> o){switch(o){case Ok<int> or not Ok<int>:return 1;}}\n", "1\n1\n" };
        yield return new object[] { "n19-x07-vec-or-not-complement", "WriteLine(F(4));WriteLine(F(1));static int F(int a){Option<Vec<int>> o = MkV(a);switch(o){case Some<Vec<int>> or not Some<Vec<int>>:return 1;}}\nstatic Option<Vec<int>> MkV(int a) { if (a > 2) { Vec<int> v = [a, a + 1]; return Some(v); } return None; }\n", "1\n1\n" };
        yield return new object[] { "n19-x08-not-none-only", "WriteLine(F(Some(4)));WriteLine(F(None));static int F(Option<int> o){switch(o){case not NoneType:return 1;}return 2;}\n", "1\n2\n" };
        yield return new object[] { "n19-x09-rvalue-or-not-complement", "WriteLine(F(Some(4)));WriteLine(F(None));static int F(Option<int> o){switch(Id(o)){case Some<int> or not Some<int>:return 1;}}\nstatic Option<int> Id(Option<int> o) => o;\n", "1\n1\n" };
    }

    // Managed, Stage-0 native and vib-self native (-O3, with and without ASan/LSan) print the same output, so every
    // linear payload is disposed exactly once and a tested place keeps its value.
    [Theory]
    [MemberData(nameof(RunPrograms))]
    public Task AcceptedProgramsRunIdentically(string name, string source, string expected)
    {
        Assert.False(string.IsNullOrEmpty(name));
        return Round11AuditAssertions.AssertDifferential(source, expected, includeUnoptimized: false);
    }

    private static string[] SelfIds((int Exit, string Output, string Error) self) =>
        Regex.Matches(self.Output + self.Error, @"VIB\d{3}").Select(match => match.Value).Distinct().OrderBy(id => id).ToArray();

    private static void WithSource(string name, string source, Action<string> action)
    {
        string directory = Path.Combine(Path.GetTempPath(), $"vibranium-r12-self-linear-union-switch-{name}-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        try
        {
            string path = Path.Combine(directory, "Program.cs");
            File.WriteAllText(path, source);
            action(path);
        }
        finally { Directory.Delete(directory, recursive: true); }
    }

    private static (int Exit, string Output, string Error) RunSelf(string path)
    {
        Assert.True(File.Exists(Round11AuditAssertions.SelfCompiler), "Build src/vib-self/VibraniumSelfCompiler.csproj before running self-hosted tests.");
        var start = new ProcessStartInfo(Round11AuditAssertions.DotnetExe)
        {
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
        };
        foreach (string argument in new[] { Round11AuditAssertions.SelfCompiler, "check", path, "--sysroot", Path.Combine(Round11AuditAssertions.RepoRoot, "src") })
            start.ArgumentList.Add(argument);
        using var process = Process.Start(start)!;
        var output = process.StandardOutput.ReadToEndAsync();
        var error = process.StandardError.ReadToEndAsync();
        if (!process.WaitForExit(30_000))
        {
            process.Kill(entireProcessTree: true);
            process.WaitForExit();
            Assert.Fail("Self source validation must terminate within thirty seconds.");
        }
        return (process.ExitCode, output.GetAwaiter().GetResult(), error.GetAwaiter().GetResult());
    }
}
